<script setup lang="ts">
import {ref,computed,watch,onMounted} from 'vue';
import {api,ApiError} from '../api';
import {useWorkspace,useSession,type WorkTab} from '../stores';
import Modal from '../components/Modal.vue';
const props=defineProps<{tab:WorkTab}>(),work=useWorkspace(),session=useSession(),copying=computed(()=>props.tab.kind==='task-copy'),data=ref<any>(null),form=ref<any>({title:'',users:[],start:'',end:''}),loading=ref(false),error=ref(''),confirming=ref(false),pending=ref<any>(null),result=ref<any>(null),search=ref(''),department=ref(''),baseline=ref('');
props.tab.submitOnly=true;
const departments=computed(()=>Array.from(new Set((data.value?.people || []).map((p:any)=>p.department || '未分部門'))).sort() as string[]);
const visible=computed(()=>(data.value?.people || []).filter((p:any)=>(!department.value||(p.department || '未分部門')===department.value)&&[p.full_name,p.email,p.job_title,p.department].join(' ').toLowerCase().includes(search.value.toLowerCase())));
const selected=computed(()=>(data.value?.people || []).filter((p:any)=>form.value.users.includes(p.id)));
async function load(){loading.value=true;error.value='';try{data.value=await api<any>('task-dispatch?id='+props.tab.recordId);form.value={title:data.value.template.title+' (副本)',users:Array.from(new Set([data.value.actor,...data.value.collaborators.map((c:any)=>c.user_id)])),start:data.value.assignment?.planned_start_date || '',end:data.value.assignment?.planned_end_date || ''};baseline.value=JSON.stringify(form.value);props.tab.dirty=false;props.tab.title=(copying.value?'複製 · ':'指派 · ')+data.value.template.title;}catch(e){error.value=(e as Error).message;}finally{loading.value=false;}}
watch(form,()=>{props.tab.dirty=!!data.value&&!result.value&&JSON.stringify(form.value)!==baseline.value;},{deep:true});
function begin(){error.value='';confirming.value=true;}
async function submit(){props.tab.busy=true;error.value='';try{pending.value ||= {id:props.tab.recordId,version:data.value.template.workspace_version,assignment:data.value.assignment?{id:data.value.assignment.id,version:data.value.assignment.workspace_version}:null,operation:copying.value?'copy':'assign',writeId:crypto.randomUUID(),...JSON.parse(JSON.stringify(form.value))};result.value=await api<any>('task-dispatch',{method:'POST',body:JSON.stringify(pending.value)});pending.value=null;props.tab.dirty=false;confirming.value=false;}catch(e){error.value=(e as Error).message;if(e instanceof ApiError && e.status===400)pending.value=null;}finally{props.tab.busy=false;}}
onMounted(load);
</script>
<template>
 <header class="page-heading"><div><p class="eyebrow">任務管理 / {{copying?'範本複製':'獨立派發'}}</p><h1>{{copying?'複製任務範本':'派發整份流程'}}</h1><p v-if="data" class="muted">{{data.template.title}}</p></div><button class="primary" :disabled="!data || loading || tab.busy || !!result" @click="begin">{{copying?'確認副本內容':'確認人員與日期'}}</button></header>
 <p v-if="error && !confirming" role="alert" class="notice error">{{error}}</p><p v-if="loading" role="status">載入範本與現行指派…</p><button v-if="!data && !loading" @click="load">重新載入</button>
 <div v-if="result" class="notice" role="status"><p>{{copying?'新範本與待處理任務已建立。':'指派已更新，既有執行紀錄保留。'}}</p><div class="button-row"><button @click="work.open('task-management-detail','',result.templateId)">開啟管理明細</button><button v-if="session.data?.capabilities.tasks" @click="work.open('task-runner','',result.assignmentId)">開啟我的任務</button></div></div>
 <div v-if="pending" class="notice"><p>上次提交尚未確認，請重試同一操作；遇到版本衝突可另開最新版本核對，原稿保留。</p><button :disabled="tab.busy" @click="work.open(tab.kind,'',tab.recordId)">另開最新版本核對</button></div>
 <fieldset v-if="data" class="dispatch-form" :disabled="tab.busy || !!pending || !!result"><legend>{{copying?'副本設定':'人員與時程'}}</legend>
 <template v-if="copying"><label>副本標題<input v-model="form.title" maxlength="300" required/></label><p>複製描述、主子項與部門區段，沿用最新現行指派的協作者及其區段，並加入你本人。新指派的總日期留空，執行紀錄與進度重新開始。</p><p v-if="!data.assignment" class="notice">沒有現行指派，副本會建立一份只指派給你的待處理任務。</p><p>原協作人員：{{data.collaborators.map((c:any)=>data.people.find((p:any)=>p.id===c.user_id)?.full_name || '未命名成員').join('、') || '無'}}</p></template>
 <template v-else><p class="notice">這是整份流程的派發：選入人員可操作全部區段，會取代目前的協作區段限制。若只要調整部門區段人員，請使用「編輯範本」。</p><p>{{data.assignment?'更新最新一筆未封存指派，保留既有進度與紀錄。':'目前沒有未封存指派，將建立新任務，既有封存紀錄保持不變。'}} 你本人一定會加入。</p><div class="filter-bar"><label>預計開始<input type="date" v-model="form.start"/></label><label>預計結束<input type="date" v-model="form.end" :min="form.start || undefined"/></label></div><p>已選 {{selected.length}} 人：{{selected.map((p:any)=>p.full_name || p.email).join('、')}}</p><div class="filter-bar"><label>搜尋人員<input v-model="search" type="search"/></label><label>部門<select v-model="department"><option value="">全部部門</option><option v-for="d in departments" :key="d">{{d}}</option></select></label></div><div class="dispatch-people"><label v-for="person in visible" :key="person.id"><input type="checkbox" v-model="form.users" :value="person.id" :disabled="person.id===data.actor"/><span>{{person.full_name || person.email || '未命名成員'}}{{person.id===data.actor?'（你，必含）':''}}<small>{{person.department || '未分部門'}} · {{person.job_title || person.email}}</small></span></label><p v-if="!visible.length">沒有符合條件的人員。</p></div></template>
 </fieldset>
 <Modal v-if="confirming" :title="copying?'確認複製範本':'確認派發整份流程'" :busy="tab.busy" @cancel="confirming=false"><p v-if="copying">建立「{{form.title}}」，保留流程結構與現行協作區段，進度重新開始。原範本不變。</p><p v-else>將 {{selected.length}} 人指派為整份流程的協作者，包含你本人。這些人可操作全部區段；未選入的原協作者將失去這筆指派的存取，歷史紀錄保留。</p><p v-if="error" role="alert" class="notice error">{{error}}</p><div class="dialog-actions"><button :disabled="tab.busy" @click="confirming=false">取消</button><button class="primary" :disabled="tab.busy" @click="submit">{{tab.busy?'處理中…':copying?'建立副本':'確認派發'}}</button></div></Modal>
</template>
<style scoped>
.dispatch-form{border:0;padding:0;min-width:0;margin-top:24px}.dispatch-form>label{display:grid;gap:8px;max-width:800px;margin:16px 0}.dispatch-people{display:grid;grid-template-columns:repeat(auto-fit,minmax(240px,1fr));gap:16px;max-height:480px;overflow:auto;padding:4px}.dispatch-people label{display:flex;align-items:flex-start;gap:10px;overflow-wrap:anywhere}.dispatch-people input{width:20px;height:20px;flex-shrink:0}.dispatch-people small{display:block;font-size:12px;color:var(--muted,#64705d);margin-top:5px}
</style>
